          lines == other.lines;
}

class NetShards {
  final List<NetEntrustedInfo> entrusted;
  final List<NetHeldInfo> held;

  const NetShards({required this.entrusted, required this.held});

  @override
  int get hashCode => entrusted.hashCode ^ held.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is NetShards &&
          runtimeType == other.runtimeType &&
          entrusted == other.entrusted &&
          held == other.held;
}

/// One item this node shares (`mnnn net shared`).
class NetShareInfo {
  final String id;
  final String shortId;
  final String kind;
  final String name;
  final String with_;

  const NetShareInfo({
    required this.id,
    required this.shortId,
    required this.kind,
    required this.name,
    required this.with_,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      shortId.hashCode ^
      kind.hashCode ^
      name.hashCode ^
      with_.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is NetShareInfo &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          shortId == other.shortId &&
          kind == other.kind &&
          name == other.name &&
          with_ == other.with_;
}

/// What `mnnn net status` shows: the node and counts, no secrets.
class NetStatus {
  final String label;
  final String? peerId;
  final String? fingerprint;
  final bool running;
  final PlatformInt64? pid;
  final PlatformInt64? startedAt;
  final String nat;
  final bool mdns;
  final bool relayServer;
  final List<String> addresses;
  final List<String> reservations;
  final PlatformInt64 connected;
  final PlatformInt64 exchangesActive;
  final PlatformInt64 incoming;
  final PlatformInt64 shared;

  const NetStatus({
    required this.label,
    this.peerId,
    this.fingerprint,
    required this.running,
    this.pid,
    this.startedAt,
    required this.nat,
    required this.mdns,
    required this.relayServer,
    required this.addresses,
    required this.reservations,
    required this.connected,
    required this.exchangesActive,
    required this.incoming,
    required this.shared,
  });

  @override
  int get hashCode =>
      label.hashCode ^
      peerId.hashCode ^
      fingerprint.hashCode ^
      running.hashCode ^
      pid.hashCode ^
      startedAt.hashCode ^
      nat.hashCode ^
      mdns.hashCode ^
      relayServer.hashCode ^
      addresses.hashCode ^
      reservations.hashCode ^
      connected.hashCode ^
      exchangesActive.hashCode ^
      incoming.hashCode ^
      shared.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is NetStatus &&
          runtimeType == other.runtimeType &&
          label == other.label &&
          peerId == other.peerId &&
          fingerprint == other.fingerprint &&
          running == other.running &&
          pid == other.pid &&
          startedAt == other.startedAt &&
          nat == other.nat &&
          mdns == other.mdns &&
          relayServer == other.relayServer &&
          addresses == other.addresses &&
          reservations == other.reservations &&
          connected == other.connected &&
          exchangesActive == other.exchangesActive &&
          incoming == other.incoming &&
          shared == other.shared;
}
